pub fn normalize(v: f32) -> f32 {
    if v.is_nan() { 0.0 } else { v }
}

clamp:
pub fn clamp(&self, val: f32) -> f32 {
            match *self {
                Self::All => val,
                Self::NonNegative => val.max(0.),
                Self::AtLeastOne => val.max(1.),
                Self::ZeroToOne => val.clamp(0., 1.),
            }
        }

